// FSRS-6 conformance: Fsrs.js against py-fsrs's own output.
//
//   node tests/fsrs.test.mjs
//
// tests/fsrs-vectors.json is generated by tools/gen_fsrs_vectors.py from the
// pinned py-fsrs. Every value there is upstream's answer for the same input.

import { readFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const here = dirname(fileURLToPath(import.meta.url))
export function loadFsrs() {
  const src = readFileSync(join(here, "..", "Fsrs.js"), "utf8").replace(/^\.pragma library$/m, "")
  const F = {}
  const names = [...src.matchAll(/^(?:function|var) ([A-Za-z_]\w*)/gm)].map((m) => m[1])
  new Function("exports", `${src}\nfor (const k of ${JSON.stringify(names)}) exports[k] = eval(k)`)(F)
  return F
}

const F = loadFsrs()
const V = JSON.parse(readFileSync(join(here, "fsrs-vectors.json"), "utf8"))
const cfg = F.config({ fuzz: false })

let pass = 0, fail = 0
const failures = []
const close = (actual, expected, label) => {
  const tol = 1e-9 * Math.max(1, Math.abs(expected))
  if (Math.abs(actual - expected) <= tol) pass++
  else { fail++; failures.push(`${label}: got ${actual}, want ${expected}`) }
}
const same = (actual, expected, label) => {
  if (actual === expected) pass++
  else { fail++; failures.push(`${label}: got ${actual}, want ${expected}`) }
}

V.parameters.forEach((p, i) => close(F.PARAMETERS[i], p, "w" + i))
same(F.PARAMETERS.length, V.parameters.length, "21 weights")
close(F.decay(cfg.parameters), V.decay, "decay")
close(F.curveFactor(cfg.parameters), V.factor, "factor")
for (const [r, e] of V.initial_stability) close(F.initialStability(cfg, r), e, `S0(${r})`)
for (const [r, e] of V.initial_difficulty) close(F.initialDifficulty(cfg, r), e, `D0(${r})`)
for (const [d, r, e] of V.next_difficulty) close(F.nextDifficulty(cfg, d, r), e, `D'(${d},${r})`)
for (const [s, r, e] of V.short_term_stability) close(F.shortTermStability(cfg, s, r), e, `Sst(${s},${r})`)
for (const [s, d, rv, g, e] of V.recall_stability)
  close(F.recallStability(cfg, s, d, rv, g), e, `Sr(${s},${d},${rv},${g})`)
for (const [s, d, rv, e] of V.forget_stability)
  close(F.forgetStability(cfg, s, d, rv), e, `Sf(${s},${d},${rv})`)
for (const [s, e] of V.next_interval) same(F.nextIntervalDays(cfg, s), e, `I(${s})`)
for (const [s, t, e] of V.retrievability) close(F.retrievabilityAfter(cfg, s, t), e, `R(${s},${t})`)

for (const sc of V.scenarios) {
  const fuzzing = sc.fuzz >= 0
  const c = F.config({ fuzz: fuzzing })
  let card = null
  sc.steps.forEach((st, i) => {
    card = F.review(card, st.rating, V.start + st.at, c, fuzzing ? sc.fuzz : undefined)
    const where = `${sc.name}[${i}]`
    same(card.state, st.state, where + " state")
    same(card.step, st.step, where + " step")
    close(card.stability, st.stability, where + " stability")
    close(card.difficulty, st.difficulty, where + " difficulty")
    same(card.due - V.start, st.due, where + " due")
  })
}

// Half-even rounding is what keeps the fuzz path on upstream's day.
same(F.roundHalfEven(2.5), 2, "2.5 rounds to 2")
same(F.roundHalfEven(3.5), 4, "3.5 rounds to 4")

// A review never mutates the card it is given.
{
  const before = F.review(null, 3, V.start, cfg)
  const snapshot = JSON.stringify(before)
  F.review(before, 1, V.start + 600, cfg)
  same(JSON.stringify(before), snapshot, "the card passed in is untouched")
}

for (const f of failures.slice(0, 20)) console.log("  FAIL " + f)
console.log(`\nfsrs: ${pass} passed, ${fail} failed (${V.generator}, ${V.scenarios.length} scenarios)`)
if (fail) process.exit(1)
